'use strict';
function projectSummary(p){if(!p)return '';const pr=progress(p.tasks);return `<section class="board-summary project-view-summary"><div><strong style="color:${p.color}">${pr.pct}%</strong><p>Tiến độ dự án</p></div><div class="grow"><div class="progress-meta"><span>${pr.done}/${pr.total} đơn vị hoàn thành</span><span>${p.tasks.filter(t=>t.col==='Done').length}/${p.tasks.length} việc hoàn thành</span></div>${bar(pr.pct,p.color)}<p>Mỗi công việc và mỗi mục checklist là một đơn vị.</p></div></section>`;}
const timelineBeforePolish=workTimeline;workTimeline=function(){const html=timelineBeforePolish();const split=html.indexOf('<section class="panel">');return active&&split>=0?html.slice(0,split)+projectSummary(project())+html.slice(split):html;};
const calendarBeforePolish=workCalendar;workCalendar=function(){const html=calendarBeforePolish(),i=html.indexOf('<div class="month-controls">');return active&&i>=0?html.slice(0,i)+projectSummary(project())+html.slice(i):html;};
function projectMatches(p,q=query){return [p.name,p.description,...(p.keywords||[]).map(k=>k.name)].join(' ').toLocaleLowerCase('vi').includes(q.toLocaleLowerCase('vi'));}
const foundBeforePolish=found;found=function(t){return foundBeforePolish(t)||!!query&&projectMatches(t.project||data.projects.find(p=>p.tasks.some(x=>x.id===t.id))||{name:'',description:''});};
const tasksBeforePolish=tasksPage;tasksPage=function(){return (query?'<section class="project-search-results"><h2>Dự án phù hợp</h2><div class="project-grid">'+visibleProjects().filter(p=>projectMatches(p)).map(projectCard).join('')+'</div></section>':'')+tasksBeforePolish();};
const projectFormBeforePolish=projectForm;projectForm=function(p){projectFormBeforePolish(p);$('#editor').classList.add('project-edit-dialog');$('#editor').addEventListener('close',()=>$('#editor').classList.remove('project-edit-dialog'),{once:true});const body=$('#editor-body');body.insertAdjacentHTML('beforeend',keywordEditor(p));const form=$('#editor-form'),submit=form.onsubmit;form.onsubmit=e=>{e.preventDefault();const keywords=[...$('#keyword-rows').children].map(row=>({name:row.querySelector('input[type=text]').value.trim(),color:row.querySelector('input[type=color]').value})).filter(k=>k.name);if(new Set(keywords.map(k=>k.name.toLocaleLowerCase('vi'))).size!==keywords.length)return notify('Tên từ khóa không được trùng nhau.');if(!form.checkValidity())return form.reportValidity();submit(e);if(!$('#editor').open){const target=p||project();if(target){target.keywords=keywords;save();render();}}};};
function reorderProjectTabs(from,to,after=false){const a=project(from),b=project(to);if(!a||!b||a===b||a.archived||b.archived||!!a.pinned!==!!b.pinned)return false;const list=data.projects.filter(p=>p.id!==from),i=list.findIndex(p=>p.id===to);list.splice(i+(after?1:0),0,a);data.projects=list;save();render();return true;}
let movingTab=null,suppressTabClickUntil=0;
document.addEventListener('dragstart',e=>{const tab=e.target.closest('#tabs .tab[data-project]');if(!tab)return;movingTab=tab.dataset.project;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',movingTab);tab.classList.add('tab-moving');});
document.addEventListener('dragover',e=>{const tab=e.target.closest('#tabs .tab[data-project]');if(movingTab&&tab){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{const tab=e.target.closest('#tabs .tab[data-project]');if(!movingTab||!tab)return;e.preventDefault();const r=tab.getBoundingClientRect();reorderProjectTabs(movingTab,tab.dataset.project,e.clientX>r.left+r.width/2);movingTab=null;suppressTabClickUntil=Date.now()+250;});
document.addEventListener('dragend',()=>{movingTab=null;document.querySelectorAll('.tab-moving').forEach(n=>n.classList.remove('tab-moving'));});
document.addEventListener('keydown',e=>{const tab=e.target.closest('#tabs .tab[data-project]');if(!tab||!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const list=visibleProjects().filter(p=>!!p.pinned===!!project(tab.dataset.project).pinned),i=list.findIndex(p=>p.id===tab.dataset.project),next=list[i+(e.key==='ArrowRight'?1:-1)];if(next){reorderProjectTabs(tab.dataset.project,next.id,e.key==='ArrowRight');document.querySelector('#tabs [data-project="'+tab.dataset.project+'"]').focus();}});
function openDueWork(group){const all=dueAlerts(),late=all.filter(t=>t.notice==='Quá hạn'),key=group||(late.length?'late':'soon'),tasks=all.filter(t=>key==='late'?t.notice==='Quá hạn':t.notice==='Sắp đến hạn');modal('<h2>Công việc cần chú ý</h2><div class="due-work-tabs"><button type="button" class="btn '+(key==='late'?'primary':'')+'" data-due-list="late">Quá hạn · '+late.length+'</button><button type="button" class="btn '+(key==='soon'?'primary':'')+'" data-due-list="soon">Sắp đến hạn · '+(all.length-late.length)+'</button></div><div class="due-work-list">'+(workTaskList(tasks,10000)||'<p class="empty">Không có công việc trong nhóm này.</p>')+'</div>',null,true);}
document.addEventListener('click',e=>{if(Date.now()<suppressTabClickUntil&&e.target.closest('#tabs [data-project]')){e.preventDefault();e.stopImmediatePropagation();return;}const due=e.target.closest('[data-open-due],[data-due-list]');if(due){e.preventDefault();e.stopImmediatePropagation();openDueWork(due.dataset.dueList);return;}const archive=e.target.closest('[data-project-archive]');if(archive){const p=project(archive.dataset.projectArchive);if(!p||p.archived)return;e.preventDefault();e.stopImmediatePropagation();modal('<h2>Lưu trữ dự án?</h2><p class="help-copy"><strong>'+esc(p.name)+'</strong> sẽ được chuyển vào Lưu trữ. Trạng thái, checklist và tệp được giữ nguyên để khôi phục sau. Dự án sẽ ngừng nhắc hạn.</p>',()=>{if(!data.projects.includes(p))return;p.archived=true;save();$('#editor').close();go('archive');notify('Đã lưu trữ dự án.');});}},true);
const alertsBeforePolish=refreshDueAlerts;refreshDueAlerts=function(){alertsBeforePolish();const strip=$('#due-alert-strip');if(!strip)return;const tasks=dueAlerts(),late=tasks.filter(t=>t.notice==='Quá hạn').length;strip.querySelector('strong').textContent=late+' việc quá hạn · '+(tasks.length-late)+' việc đến hạn trong 3 ngày';strip.querySelector('[data-open-due]').innerHTML=svgIcon('tasks')+'<span>'+(late?'Xem việc quá hạn':'Xem việc sắp hạn')+'</span>';strip.querySelector('[data-snooze-due]').innerHTML=svgIcon('clock')+'<span>Ẩn 30 phút</span>';const header=$('.topbar'),position=getComputedStyle(header).position;strip.style.top=['sticky','fixed'].includes(position)?header.offsetHeight+'px':'0px';};
Object.assign(iconPaths,{dashboard:'M12 4c-3 0-7 4-7 8s4 7 7 7 7-3 7-7-4-8-7-8Z M8 13c0-2 2-4 4-4s4 2 4 4 M12 12v5',tasks:'M5 6c0-2 3-3 7-3s7 1 7 3v12c0 2-3 3-7 3s-7-1-7-3V6Z M8 9l2 2 5-5 M8 15h7',notes:'M6 4c4-2 8-2 12 0v15c-4-2-8-2-12 0V4Z M9 7c2-1 4-1 6 0 M9 11h6',archive:'M5 8c0-2 14-2 14 0v10c0 3-14 3-14 0V8Z M4 5c0-2 16-2 16 0v3H4V5Z M10 12h4',trash:'M6 7l1 12c0 2 10 2 10 0l1-12 M4 6c4-2 12-2 16 0 M9 4c0-2 6-2 6 0 M10 10v7 M14 10v7',settings:'M12 3c3 0 4 3 6 4s3 3 2 6-4 3-5 6-5 2-6 0-5-3-5-6 2-5 4-6 1-4 4-4Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',versions:'M5 8c1-5 12-6 15 1s-4 14-11 10 M4 4v5h5 M12 7v6l3 2',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9c0-4 7-4 6 0-1 2-3 1-3 5 M12 17h.01'});
const renderBeforePolish=render;render=function(){renderBeforePolish();const settingsIcon=document.querySelector('#settings-slot .ui-icon path');if(settingsIcon)settingsIcon.setAttribute('d',iconPaths.settings);const helpButton=document.querySelector('.sidebar [data-action=help]');if(helpButton)helpButton.innerHTML=svgIcon('help')+'<span>Hướng dẫn</span>';const home=$('#tabs .tab-home');if(home){home.innerHTML=svgIcon('leaf')+'<b>'+visibleProjects().length+'</b>';home.title=visibleProjects().length+' dự án đang chạy · Về tổng quan';}document.querySelectorAll('#tabs .tab[data-project]').forEach(tab=>{tab.draggable=true;tab.title+=' · Kéo để sắp xếp hoặc Alt + ←/→';});document.querySelectorAll('.sidebar .nav[data-view]').forEach(b=>{const icon=b.querySelector('.ui-icon path');if(icon)icon.setAttribute('d',iconPaths[b.dataset.view]||iconPaths[b.dataset.view==='trash'?'trash':'notes']||iconPaths.leaf);});};
const cardBeforeKeywords=projectCard;projectCard=function(p){return cardBeforeKeywords(p).replace('<div class="progress-meta">',(p.keywords?.length?'<div class="project-keyword-chips label-chips">'+p.keywords.map(k=>'<span class="label-chip" style="--label:'+k.color+'">'+esc(k.name)+'</span>').join('')+'</div>':'')+'<div class="progress-meta">');};
function showTimePicker(input,withTime,trigger){const previous=input.value,initial=previous?.slice(0,10)||today(),d=new Date(initial+'T12:00:00Z');let month=d.getUTCMonth(),year=d.getUTCFullYear(),selected=initial,hour=previous.slice(11,13)||'08',minute=previous.slice(14,16)||'00';const dialog=document.createElement('dialog');dialog.className='time-picker-dialog';dialog.setAttribute('aria-label','Chọn ngày'+(withTime?' và giờ':''));dialog.innerHTML='<div class="picker-head"><h3>Chọn ngày'+(withTime?' và giờ':'')+'</h3><button type="button" class="icon-btn" data-picker-close aria-label="Đóng">×</button></div><div class="picker-month"><button type="button" data-picker-prev aria-label="Tháng trước">‹</button><strong id="picker-month-title"></strong><button type="button" data-picker-next aria-label="Tháng sau">›</button></div><div id="picker-days" class="picker-days"></div>'+(withTime?'<div class="picker-clock"><label>Giờ<select id="picker-hour">'+Array.from({length:24},(_,i)=>'<option value="'+String(i).padStart(2,'0')+'" '+(i===Number(hour)?'selected':'')+'>'+String(i).padStart(2,'0')+'</option>').join('')+'</select></label><span>:</span><label>Phút<select id="picker-minute">'+Array.from({length:60},(_,i)=>'<option value="'+String(i).padStart(2,'0')+'" '+(i===Number(minute)?'selected':'')+'>'+String(i).padStart(2,'0')+'</option>').join('')+'</select></label></div><small>Giờ Việt Nam</small>':'')+'<div class="picker-actions"><button type="button" class="text-btn" data-picker-clear>Xóa lịch</button><button type="button" class="text-btn" data-picker-today>Hôm nay</button><button type="button" class="btn primary" data-picker-apply>Áp dụng</button></div>';document.body.append(dialog);function draw(){dialog.querySelector('#picker-month-title').textContent='Tháng '+(month+1)+', '+year;const first=(new Date(Date.UTC(year,month,1)).getUTCDay()+6)%7,count=new Date(Date.UTC(year,month+1,0)).getUTCDate();dialog.querySelector('#picker-days').innerHTML=['T2','T3','T4','T5','T6','T7','CN'].map(n=>'<small>'+n+'</small>').join('')+'<span></span>'.repeat(first)+Array.from({length:count},(_,i)=>{const value=year+'-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return '<button type="button" data-picker-day="'+value+'" class="'+(selected===value?'selected ':'')+(value===today()?'is-today':'')+'" aria-label="'+value+'" aria-pressed="'+(selected===value)+'">'+(i+1)+'</button>';}).join('');}function apply(value){input.value=value;trigger.textContent=value?value.slice(0,10).split('-').reverse().join('/')+(withTime?' · '+value.slice(11):''):'Chọn ngày'+(withTime?' và giờ':'');input.dispatchEvent(new Event('change',{bubbles:true}));dialog.close();trigger.focus();}dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-picker-close'))dialog.close();if(b.dataset.pickerDay){selected=b.dataset.pickerDay;draw();}if(b.hasAttribute('data-picker-prev')||b.hasAttribute('data-picker-next')){month+=b.hasAttribute('data-picker-next')?1:-1;if(month>11){month=0;year++;}if(month<0){month=11;year--;}draw();}if(b.hasAttribute('data-picker-today')){selected=today();const x=new Date(selected+'T12:00:00Z');month=x.getUTCMonth();year=x.getUTCFullYear();draw();}if(b.hasAttribute('data-picker-clear'))apply('');if(b.hasAttribute('data-picker-apply'))apply(selected+(withTime?'T'+dialog.querySelector('#picker-hour').value+':'+dialog.querySelector('#picker-minute').value:''));});dialog.addEventListener('close',()=>dialog.remove());draw();dialog.showModal();}
const taskFormBeforeTime=taskForm;taskForm=function(...args){taskFormBeforeTime(...args);document.querySelectorAll('#editor-body input[type=date],#editor-body input[type=datetime-local]').forEach(input=>{const time=input.type==='datetime-local';input.type='hidden';const button=document.createElement('button');button.type='button';button.className='date-field-trigger';button.textContent=input.value?input.value.slice(0,10).split('-').reverse().join('/')+(time?' · '+input.value.slice(11):''):'Chọn ngày'+(time?' và giờ':'');button.setAttribute('aria-label',input.name==='due'?'Hạn hoàn thành':input.name==='start'?'Bắt đầu':'Kết thúc');button.onclick=()=>showTimePicker(input,time,button);input.after(button);});};
const assetPanelBeforePolish=assetPanel;assetPanel=async function(...args){try{await assetPanelBeforePolish(...args);const input=$('#large-file');if(!input)return;input.hidden=true;input.insertAdjacentHTML('afterend','<div class="upload-dropzone" id="upload-dropzone"><span>'+svgIcon('leaf')+'</span><h3>Thêm tài liệu vào dự án</h3><p>Kéo tệp vào đây hoặc chọn từ thiết bị</p><button type="button" class="btn primary" id="choose-upload">Chọn tệp</button><small>Tối đa 25 MB mỗi tệp · Tệp được lưu riêng tư</small></div>');$('#choose-upload').onclick=()=>input.click();const zone=$('#upload-dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('is-dragging');};zone.ondragleave=()=>zone.classList.remove('is-dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('is-dragging');if(input.disabled)return;input.files=e.dataTransfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));};}catch(e){notify(e.message);}};
let touchTab=null,touchHold;
document.addEventListener('pointerdown',e=>{const tab=e.target.closest('#tabs .tab[data-project]');if(!tab||e.pointerType==='mouse')return;touchTab={id:tab.dataset.project,x:e.clientX,y:e.clientY,ready:false,target:null};touchHold=setTimeout(()=>{if(touchTab){touchTab.ready=true;tab.classList.add('tab-moving');}},450);});
document.addEventListener('pointermove',e=>{if(!touchTab)return;if(!touchTab.ready){if(Math.hypot(e.clientX-touchTab.x,e.clientY-touchTab.y)>10){clearTimeout(touchHold);touchTab=null;}return;}e.preventDefault();const tab=document.elementFromPoint(e.clientX,e.clientY)?.closest('#tabs .tab[data-project]');if(tab){const r=tab.getBoundingClientRect();touchTab.target=tab.dataset.project;touchTab.after=e.clientX>r.left+r.width/2;}},{passive:false});
function endTabTouch(apply){clearTimeout(touchHold);if(touchTab?.ready){if(apply&&touchTab.target)reorderProjectTabs(touchTab.id,touchTab.target,touchTab.after);suppressTabClickUntil=Date.now()+400;}touchTab=null;document.querySelectorAll('.tab-moving').forEach(n=>n.classList.remove('tab-moving'));}
document.addEventListener('pointerup',()=>endTabTouch(true));document.addEventListener('pointercancel',()=>endTabTouch(false));

