const formBeforeCalm=taskForm;taskForm=function(...args){formBeforeCalm(...args);const body=$('#editor-body');if(!body.querySelector('[name=title]'))return;body.classList.add('task-fields');$('#editor').classList.add('task-editor');$('#editor').addEventListener('close',()=>{$('#editor').classList.remove('task-editor');body.classList.remove('task-fields');},{once:true});const title=body.querySelector('h2');title.insertAdjacentHTML('afterend','<p class="form-intro">Đặt tên rõ ràng, chọn lịch và chia nhỏ các bước thực hiện.</p>');const select=body.querySelector('select[name=priority]');if(select){select.hidden=true;const label=select.closest('label'),fieldset=document.createElement('fieldset');fieldset.className='priority-choices';fieldset.innerHTML='<legend>Mức độ</legend>'+Object.entries(PRIORITIES).map(([key,name])=>'<label class="priority-choice '+key+'"><input type="radio" name="priority-choice" value="'+key+'" '+(select.value===key?'checked':'')+'><span>'+esc(name)+'</span></label>').join('')+'<label class="priority-clear priority-choice unclassified"><input type="radio" name="priority-choice" value="" '+(!select.value?'checked':'')+'> Chưa phân loại</label>';fieldset.onchange=e=>{select.value=e.target.value;};label.hidden=true;label.after(fieldset);}};
